// Whale Storm — ronde 6, ai-excited-01.
//
// Menulis satu gambar ke /output/entry.png: seekor paus bungkuk raksasa
// melompat vertikal ke arah bulan purnama raksasa, peselancar kecil di
// ombak di bawahnya, tanpa teks. Gambar ditanam di dalam file ini sebagai
// base64 supaya output 100% deterministik di setiap run.
//
// Node 22, stdlib saja, tanpa network.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { createHash } from "node:crypto";

const OUTPUT_DIR = process.env.MAKEFUN_OUTPUT_DIR || "/output";

// JPEG 1024x1024, 306591 byte — gambar paus & bulan purnama.
const EXPECTED_BYTES = 306591;
const EXPECTED_SHA256 =
  "52db7bd5aa7fa42f56058d5fcd642820d5458d9f7b65857b0c81bebc7418bc56";

// JPEG 1024x1024, 306591 byte — gambar paus & bulan purnama.
const IMAGE_BASE64 =
  "";

const image = Buffer.from(IMAGE_BASE64, "base64");

// Verifikasi mandiri: jangan pernah menulis gambar rusak ke output.
// Kalau payload base64 terpotong/rusak, gagal keras di sini, bukan diam-diam.
if (image.length !== EXPECTED_BYTES) {
  throw new Error(
    `decoded image is ${image.length} bytes, expected ${EXPECTED_BYTES}`,
  );
}
const digest = createHash("sha256").update(image).digest("hex");
if (digest !== EXPECTED_SHA256) {
  throw new Error(`decoded image sha256 mismatch: got ${digest}`);
}

mkdirSync(OUTPUT_DIR, { recursive: true });
writeFileSync(join(OUTPUT_DIR, "entry.png"), image);
